def affine_dec(s, a, b):
    inv = pow(a, -1, 26)
    out = ''
    for c in s:
        if c.isalpha():
            out += chr((inv * (ord(c) - 97 - b)) % 26 + 97)
        else:
            out += c
    return out
s = open('cipher.txt').read().strip()
for a in range(26):
    if a % 2 == 0 or a == 13:
        continue
    for b in range(26):
        pt = affine_dec(s, a, b)
        if 'nto{' in pt:
            print(f'a={a} b={b}: {pt}')
